-- Verify: this file owns exactly 160 rows for EH. The assertion counts only
-- rows whose path is declared in this file, so a correct re-run still passes even when
-- other rows exist for EH.
do $$
declare cnt integer;
begin
  select count(*) into cnt
  from public.locations
  where country_code = 'EH'
    and path = any (array[
      'western-sahara',
      'western-sahara/aousserd-southern-border-zone',
      'western-sahara/aousserd-southern-border-zone/aousserd-administrative-area',
      'western-sahara/aousserd-southern-border-zone/aousserd-administrative-area/aousserd',
